import{_ as t,o as a,c as o,a2 as r}from"./chunks/framework.Boholvbs.js";const h=JSON.parse('{"title":"WordPress.org Plugin Directory — Audit Report","description":"","frontmatter":{},"headers":[],"relativePath":"dev/wordpress-org-audit-report/index.md","filePath":"dev/wordpress-org-audit-report.md"}'),d={name:"dev/wordpress-org-audit-report/index.md"};function i(s,e,n,c,l,p){return a(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="wordpress-org-plugin-directory-—-audit-report" tabindex="-1">WordPress.org Plugin Directory — Audit Report <a class="header-anchor" href="#wordpress-org-plugin-directory-—-audit-report" aria-label="Permalink to &quot;WordPress.org Plugin Directory — Audit Report&quot;">​</a></h1><blockquote><p>Data da auditoria: 2026-05-11 Versao auditada: JEO 3.6.5 Plugin: JEO WP (jeo/jeo.php) Baseado nas diretrizes oficiais: <a href="https://developer.wordpress.org/plugins/wordpress-org/detailed-plugin-guidelines/" target="_blank" rel="noreferrer">https://developer.wordpress.org/plugins/wordpress-org/detailed-plugin-guidelines/</a></p></blockquote><hr><h2 id="resumo-executivo" tabindex="-1">Resumo Executivo <a class="header-anchor" href="#resumo-executivo" aria-label="Permalink to &quot;Resumo Executivo&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Categoria</th><th>Status</th><th>Acoes Requeridas</th></tr></thead><tbody><tr><td>Licenca</td><td>ALERTA</td><td>Texto da licenca e GPL v3, mas header declara GPL-2.0+</td></tr><tr><td>readme.txt</td><td>FALHA</td><td>Faltam Tags (0/1-12), Requires PHP desatualizado</td></tr><tr><td>Seguranca — Input/Output</td><td>FALHA</td><td>CSS injection via loaders.php; AJAX sem capability check</td></tr><tr><td>Seguranca — REST/AJAX</td><td>PASS</td><td>Nonces e permission_callbacks presentes</td></tr><tr><td>Seguranca — DB/Arquivos</td><td>PASS</td><td>Queries preparadas, caminhos hardcoded</td></tr><tr><td>Privacidade</td><td>FALHA</td><td>Sem wp_add_privacy_policy_content(), sem exporter/eraser</td></tr><tr><td>External Assets</td><td>ALERTA</td><td>Select2 do CDN, MapLibre do unpkg, Google Fonts</td></tr><tr><td>Dashboard Hijacking</td><td>PASS</td><td>Sem redirecionamentos forçados ou notificacoes intrusivas</td></tr><tr><td>Trialware/Upsell</td><td>PASS</td><td>Sem funcionalidade bloqueada</td></tr><tr><td>Tracking</td><td>PASS</td><td>Sem analytics/telemetry</td></tr><tr><td>Bibliotecas WP</td><td>PASS</td><td>Nao inclui jQuery ou outras libs padrao localmente</td></tr><tr><td>Uninstall</td><td>FALHA</td><td>Cleanup incompleto — deixa AI logs e vector stores</td></tr><tr><td>Build/Code Quality</td><td>PASS</td><td>Codigo legivel, sem eval/exec, sem ofuscacao</td></tr></tbody></table><p><strong>Veredicto: NAO ADERENTE para submissao na WordPress.org Plugin Directory.</strong></p><hr><h2 id="_1-licenca-diretriz-1" tabindex="-1">1. Licenca (Diretriz #1) <a class="header-anchor" href="#_1-licenca-diretriz-1" aria-label="Permalink to &quot;1. Licenca (Diretriz #1)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Item</th><th>Status</th><th>Detalhe</th></tr></thead><tbody><tr><td>LICENSE (repo root)</td><td>ALERTA</td><td>Texto e GPL v3, nao GPL v2</td></tr><tr><td>src/LICENSE.txt</td><td>ALERTA</td><td>Texto e GPL v3</td></tr><tr><td>readme.txt License</td><td>PASS</td><td>Declara GPL-2.0+</td></tr><tr><td>jeo.php License</td><td>PASS</td><td>Declara GPL-2.0+</td></tr></tbody></table><p><strong>Recomendacao:</strong> O arquivo LICENSE deveria conter o texto da GPL v2, ou o header deveria ser atualizado para GPL-3.0-or-later para alinhar com o arquivo.</p><hr><h2 id="_2-readme-txt-diretriz-12-15" tabindex="-1">2. readme.txt (Diretriz #12, #15) <a class="header-anchor" href="#_2-readme-txt-diretriz-12-15" aria-label="Permalink to &quot;2. readme.txt (Diretriz #12, #15)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Header</th><th>Status</th><th>Valor</th></tr></thead><tbody><tr><td>Contributors</td><td>PASS</td><td>earthjournalism</td></tr><tr><td>Tags</td><td>FALHA</td><td><strong>AUSENTE</strong> — necessario 1 a 12 tags</td></tr><tr><td>Tested up to</td><td>PASS</td><td>6.8.2</td></tr><tr><td>Stable tag</td><td>PASS</td><td>3.6.5</td></tr><tr><td>Requires PHP</td><td>ALERTA</td><td>8.0 (mas jeo.php exige 8.2+ em runtime)</td></tr><tr><td>Requires at least</td><td>PASS</td><td>6.6</td></tr><tr><td>License</td><td>PASS</td><td>GPL-2.0+</td></tr><tr><td>Third Party Services</td><td>PASS</td><td>Presente</td></tr></tbody></table><p><strong>Acoes:</strong></p><ol><li>Adicionar header <code>Tags:</code> com 1-12 tags relevantes (ex: maps, geolocation, gutenberg, storymap, cartography, mapbox, maplibre, blocks, interactive, journalism, openstreetmap, spatial)</li><li>Sincronizar <code>Requires PHP</code> com o runtime check (8.2).</li></ol><hr><h2 id="_3-seguranca" tabindex="-1">3. Seguranca <a class="header-anchor" href="#_3-seguranca" aria-label="Permalink to &quot;3. Seguranca&quot;">​</a></h2><h3 id="_3-1-superglobals-e-sanitizacao-—-pass" tabindex="-1">3.1 Superglobals e Sanitizacao — PASS <a class="header-anchor" href="#_3-1-superglobals-e-sanitizacao-—-pass" aria-label="Permalink to &quot;3.1 Superglobals e Sanitizacao — PASS&quot;">​</a></h3><p>Todos os acessos a <code>$_GET</code>/<code>$_POST</code> estao sanitizados via <code>sanitize_text_field</code>, <code>sanitize_key</code>, etc.</p><h3 id="_3-2-rest-api-—-pass" tabindex="-1">3.2 REST API — PASS <a class="header-anchor" href="#_3-2-rest-api-—-pass" aria-label="Permalink to &quot;3.2 REST API — PASS&quot;">​</a></h3><p>Todas as rotas REST tem <code>permission_callback</code> apropriado.</p><h3 id="_3-3-ajax-endpoints-—-alerta" tabindex="-1">3.3 AJAX Endpoints — ALERTA <a class="header-anchor" href="#_3-3-ajax-endpoints-—-alerta" aria-label="Permalink to &quot;3.3 AJAX Endpoints — ALERTA&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Endpoint</th><th>Nonce</th><th>Capability</th></tr></thead><tbody><tr><td><code>wp_ajax_jeo_geocode</code></td><td><code>check_ajax_referer</code></td><td><strong>AUSENTE</strong></td></tr><tr><td><code>wp_ajax_jeo_reverse_geocode</code></td><td><code>check_ajax_referer</code></td><td><strong>AUSENTE</strong></td></tr></tbody></table><p><strong>Recomendacao:</strong> Adicionar <code>current_user_can(&#39;edit_posts&#39;)</code> para defesa em profundidade.</p><h3 id="_3-4-output-escaping-—-falha-critica" tabindex="-1">3.4 Output Escaping — FALHA CRITICA <a class="header-anchor" href="#_3-4-output-escaping-—-falha-critica" aria-label="Permalink to &quot;3.4 Output Escaping — FALHA CRITICA&quot;">​</a></h3><p><strong>Arquivo:</strong> <code>src/includes/loaders.php</code>, funcao <code>jeo_custom_settings_css()</code></p><p>Valores das settings sao concatenados diretamente em CSS sem escape adequado:</p><ul><li><code>$jeo_font</code> usa <code>wp_kses(..., null)</code> — nao escapa aspas CSS</li><li><code>$jeo_info_font_size</code> sem casting numerico</li><li>Cores sem <code>sanitize_hex_color()</code></li></ul><p><strong>Fix necessario:</strong> Aplicar <code>esc_attr()</code> a fontes, <code>floatval()</code> a tamanhos, <code>sanitize_hex_color()</code> a cores.</p><hr><h2 id="_4-privacidade" tabindex="-1">4. Privacidade <a class="header-anchor" href="#_4-privacidade" aria-label="Permalink to &quot;4. Privacidade&quot;">​</a></h2><h3 id="_4-1-wp-add-privacy-policy-content-—-falha" tabindex="-1">4.1 wp_add_privacy_policy_content() — FALHA <a class="header-anchor" href="#_4-1-wp-add-privacy-policy-content-—-falha" aria-label="Permalink to &quot;4.1 wp_add_privacy_policy_content() — FALHA&quot;">​</a></h3><p><strong>Status:</strong> NAO implementado.</p><p>O plugin coleta e processa dados pessoais (geolocalizacao, logs de AI, vector stores).</p><p><strong>Fix:</strong> Implementar <code>wp_add_privacy_policy_content()</code> descrevendo:</p><ul><li>Servicos de terceiros usados</li><li>Retencao de dados de geolocalizacao</li><li>Retencao de logs de AI</li></ul><h3 id="_4-2-personal-data-exporter-eraser-—-falha" tabindex="-1">4.2 Personal Data Exporter / Eraser — FALHA <a class="header-anchor" href="#_4-2-personal-data-exporter-eraser-—-falha" aria-label="Permalink to &quot;4.2 Personal Data Exporter / Eraser — FALHA&quot;">​</a></h3><p><strong>Status:</strong> NAO implementados.</p><p>O plugin armazena dados pessoais em post meta (<code>_related_point</code>, <code>_jeo_ai_pending_point</code>) e CPT (<code>jeo-ai-log</code>).</p><p><strong>Fix:</strong> Registrar callbacks via <code>wp_privacy_personal_data_exporter</code> e <code>wp_privacy_personal_data_eraser</code>.</p><h3 id="_4-3-browser-geolocation-—-alerta" tabindex="-1">4.3 Browser Geolocation — ALERTA <a class="header-anchor" href="#_4-3-browser-geolocation-—-alerta" aria-label="Permalink to &quot;4.3 Browser Geolocation — ALERTA&quot;">​</a></h3><p><strong>Arquivo:</strong> <code>src/js/src/stories-near-you/stories-near-you-frontend.js</code></p><p>Chama <code>navigator.geolocation.getCurrentPosition()</code> automaticamente ao carregar a pagina, sem dialogo de consentimento.</p><p><strong>Fix:</strong> Adicionar um botao &quot;Usar minha localizacao&quot; em vez de solicitar automaticamente.</p><hr><h2 id="_5-external-assets-diretriz-8" tabindex="-1">5. External Assets (Diretriz #8) <a class="header-anchor" href="#_5-external-assets-diretriz-8" aria-label="Permalink to &quot;5. External Assets (Diretriz #8)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Dominio</th><th>Asset</th><th>Context</th><th>Status</th></tr></thead><tbody><tr><td><code>cdnjs.cloudflare.com</code></td><td>Select2 CSS/JS</td><td>Settings page</td><td>ALERTA — nao e fonte nem SaaS</td></tr><tr><td><code>unpkg.com</code></td><td>MapLibre GL JS</td><td>Admin dashboard</td><td>ALERTA — deveria usar a versao do WordPress ou bundle local</td></tr><tr><td><code>fonts.googleapis.com</code></td><td>Google Fonts</td><td>Frontend/admin</td><td>ALERTA — WP.org prefere fontes locais</td></tr><tr><td><code>fonts.openmaptiles.org</code></td><td>MapLibre glyphs</td><td>Build output</td><td><strong>REMOVIDO</strong> em correcao anterior</td></tr><tr><td><code>raw.githubusercontent.com</code></td><td>Leaflet icons</td><td>Source/build</td><td><strong>REMOVIDO</strong> em correcao anterior</td></tr></tbody></table><p><strong>Recomendacao:</strong> Bundle local do Select2 e considerar fontes locais.</p><hr><h2 id="_6-uninstall-diretriz-de-privacidade" tabindex="-1">6. Uninstall (Diretriz de Privacidade) <a class="header-anchor" href="#_6-uninstall-diretriz-de-privacidade" aria-label="Permalink to &quot;6. Uninstall (Diretriz de Privacidade)&quot;">​</a></h2><p><strong>Arquivo:</strong> <code>src/uninstall.php</code></p><table tabindex="0"><thead><tr><th>Dado</th><th>Cleanup</th><th>Status</th></tr></thead><tbody><tr><td><code>jeo-settings</code> (option)</td><td>delete_option</td><td>PASS</td></tr><tr><td>Post meta (<code>_related_point</code>, <code>_geocode_*</code>)</td><td><strong>PRESERVADO intencionalmente</strong></td><td>ALERTA</td></tr><tr><td>CPT <code>jeo-ai-log</code></td><td><strong>NAO removido</strong></td><td>FALHA</td></tr><tr><td>Vector stores (<code>wp-content/uploads/jeo-ai-store/</code>)</td><td><strong>NAO removido</strong></td><td>FALHA</td></tr><tr><td>Options auxiliares (<code>jeo_bulk_ai_cron_logs</code>, etc.)</td><td><strong>NAO removidos</strong></td><td>FALHA</td></tr><tr><td>Transients (<code>jeo_nominatim_*</code>)</td><td><strong>NAO removidos</strong></td><td>FALHA</td></tr></tbody></table><p><strong>Fix:</strong> Remover CPTs, opcoes auxiliares, transients e vector stores no uninstall. Post meta pode ser opcional.</p><hr><h2 id="_7-dashboard-hijacking-diretriz-11" tabindex="-1">7. Dashboard Hijacking (Diretriz #11) <a class="header-anchor" href="#_7-dashboard-hijacking-diretriz-11" aria-label="Permalink to &quot;7. Dashboard Hijacking (Diretriz #11)&quot;">​</a></h2><p><strong>Status: PASS</strong></p><ul><li>Sem redirecionamento pos-ativacao</li><li>Sem notificacoes persistentes ou promocionais</li><li>Sem widgets no dashboard</li><li>Sem upselling</li></ul><hr><h2 id="_8-trialware-diretriz-5" tabindex="-1">8. Trialware (Diretriz #5) <a class="header-anchor" href="#_8-trialware-diretriz-5" aria-label="Permalink to &quot;8. Trialware (Diretriz #5)&quot;">​</a></h2><p><strong>Status: PASS</strong></p><ul><li>Sem funcionalidade bloqueada por pagamento</li><li>Sem licenca/trial/upgrade</li></ul><hr><h2 id="_9-tracking-diretriz-7" tabindex="-1">9. Tracking (Diretriz #7) <a class="header-anchor" href="#_9-tracking-diretriz-7" aria-label="Permalink to &quot;9. Tracking (Diretriz #7)&quot;">​</a></h2><p><strong>Status: PASS</strong></p><ul><li>Sem analytics (Google Analytics, Matomo, etc.)</li><li>Sem tracking pixels</li><li>Sem telemetry</li><li>Sem setcookie()</li></ul><hr><h2 id="_10-bibliotecas-padrao-do-wordpress-diretriz-13" tabindex="-1">10. Bibliotecas Padrao do WordPress (Diretriz #13) <a class="header-anchor" href="#_10-bibliotecas-padrao-do-wordpress-diretriz-13" aria-label="Permalink to &quot;10. Bibliotecas Padrao do WordPress (Diretriz #13)&quot;">​</a></h2><p><strong>Status: PASS</strong></p><ul><li>Nao inclui jQuery, jQuery UI, SimplePie, PHPMailer, PHPass localmente</li><li>Usa <code>wp_enqueue_script()</code> para dependencias do WordPress</li></ul><hr><h2 id="_11-build-code-quality-diretriz-4" tabindex="-1">11. Build / Code Quality (Diretriz #4) <a class="header-anchor" href="#_11-build-code-quality-diretriz-4" aria-label="Permalink to &quot;11. Build / Code Quality (Diretriz #4)&quot;">​</a></h2><p><strong>Status: PASS</strong></p><ul><li>Codigo fonte legivel (sem obfuscacao)</li><li>Sem uso de <code>eval()</code>, <code>exec()</code>, <code>system()</code>, <code>shell_exec()</code></li><li>Bundles minificados gerados por webpack, com source disponivel em <code>src/js/src/</code></li></ul><hr><h2 id="checklist-de-acoes-para-deploy" tabindex="-1">Checklist de Acoes para Deploy <a class="header-anchor" href="#checklist-de-acoes-para-deploy" aria-label="Permalink to &quot;Checklist de Acoes para Deploy&quot;">​</a></h2><h3 id="critico-bloqueia-aprovacao" tabindex="-1">CRITICO (bloqueia aprovacao) <a class="header-anchor" href="#critico-bloqueia-aprovacao" aria-label="Permalink to &quot;CRITICO (bloqueia aprovacao)&quot;">​</a></h3><ul><li>[ ] <strong>Adicionar Tags no readme.txt</strong> (1-12 tags)</li><li>[ ] <strong>Corrigir CSS escaping</strong> em <code>loaders.php</code> (<code>jeo_custom_settings_css()</code>)</li><li>[ ] <strong>Implementar</strong> <code>wp_add_privacy_policy_content()</code></li><li>[ ] <strong>Implementar</strong> Personal Data Exporter e Eraser</li><li>[ ] <strong>Completar uninstall</strong> (remover AI logs, vector stores, opcoes auxiliares)</li></ul><h3 id="alto-recomendado" tabindex="-1">ALTO (recomendado) <a class="header-anchor" href="#alto-recomendado" aria-label="Permalink to &quot;ALTO (recomendado)&quot;">​</a></h3><ul><li>[ ] <strong>Sincronizar</strong> <code>Requires PHP</code> para 8.2 no readme.txt</li><li>[ ] <strong>Adicionar capability check</strong> aos endpoints AJAX de geocoding</li><li>[ ] <strong>Adicionar consentimento explicito</strong> para geolocalizacao no Stories Near You</li><li>[ ] <strong>Bundle local do Select2</strong> (evitar CDN externo)</li><li>[ ] <strong>Licenca:</strong> Alinhar texto do arquivo LICENSE com o header (GPL v2 ou v3)</li></ul><h3 id="medio-melhoria" tabindex="-1">MEDIO (melhoria) <a class="header-anchor" href="#medio-melhoria" aria-label="Permalink to &quot;MEDIO (melhoria)&quot;">​</a></h3><ul><li>[ ] <strong>Fontes locais:</strong> Considerar self-hosting das fontes Google</li><li>[ ] <strong>MapLibre:</strong> Documentar que o carregamento do unpkg e uma dependencia de servico</li></ul>',81)])])}const g=t(d,[["render",i]]);export{h as __pageData,g as default};
